examples.code:
set count 0
set total 0
foreach value {18 21 -1 19 23} {
    if {$value < 0} {continue}
    incr count
    set total [expr {$total + $value}]
}
puts "有效次数：$count"
puts "总和：$total"

set pending 3
while {$pending > 0} {
    puts "剩余：$pending"
    incr pending -1
}
foreach value {12 15 31 18} {
    if {$value > 30} {
        puts "首个异常：$value"
        break
    }
}

exercises.solution:
set times {12 8 15 0}
set total 0
set count 0
foreach minutes $times {
    set total [expr {$total + $minutes}]
    incr count
}
puts "$count 条，共 $total 分钟"

set readings {7 -1 0 9 -2}
set emptyReadings {}
set total 0
set count 0
foreach value $readings {
    if {$value < 0} {continue}
    set total [expr {$total + $value}]
    incr count
}
set emptyTotal 0
set emptyCount 0
foreach value $emptyReadings {
    if {$value < 0} {continue}
    set emptyTotal [expr {$emptyTotal + $value}]
    incr emptyCount
}
puts "有效：$count，总和：$total"
puts "空组：$emptyCount，总和：$emptyTotal"

set readings {9 14 35 41 12}
set limit 30
set visited 0
set found "未发现"
foreach value $readings {
    incr visited
    if {$value > $limit} {
        set found $value
        break
    }
}
puts "检查 $visited 条，首个越界：$found"
